#!/usr/bin/env python3
"""Condense a captured conversation JSONL into readable dialogue + tool trace.

argv: <mode> where mode is 'dialogue' (human turns + assistant text) or
'tools' (tool_use timeline with durations). Reads JSONL on stdin.
"""
import sys, json

mode = sys.argv[1] if len(sys.argv) > 1 else 'dialogue'
atrunc = int(sys.argv[2]) if len(sys.argv) > 2 else 700

prev_ts = None
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        d = json.loads(line)
    except Exception:
        continue
    t = d.get('type')
    ts = (d.get('timestamp') or '')[11:19]
    msg = d.get('message') or {}
    content = msg.get('content')
    if t == 'user':
        if isinstance(content, str):
            txt = content
        elif isinstance(content, list):
            parts = [b.get('text', '') for b in content if isinstance(b, dict) and b.get('type') == 'text']
            txt = '\n'.join(p for p in parts if p)
        else:
            txt = ''
        if txt.strip():
            print(f'\n### [{ts}] HUMAN:\n{txt[:3000]}')
    elif t == 'assistant':
        if not isinstance(content, list):
            continue
        for b in content:
            if not isinstance(b, dict):
                continue
            if b.get('type') == 'text' and mode == 'dialogue':
                s = b.get('text', '').strip()
                if s:
                    print(f'[{ts}] A: {s[:atrunc]}')
            elif b.get('type') == 'tool_use' and mode == 'tools':
                name = b.get('name')
                inp = json.dumps(b.get('input', {}))[:200]
                print(f'[{ts}] TOOL {name} {inp}')

