SP=/tmp/claude-0/-home-user-Claudinite/5ae82424-2bbe-5b2c-9a58-95571bd2415b/scratchpad && node -e "
const fs=require('fs');
const calls=JSON.parse(fs.readFileSync('$SP/agent-calls.json','utf8'));
const specs=JSON.parse(fs.readFileSync('.claudinite/local/packs/claudinite/declared-checks.json','utf8'));
const s=specs.find(x=>x.id==='subagent-branch-named-git').guardToolCalls[0];
const toRe=(t)=>{const m=t.match(/^\/(.*)\/(\w*)\$/s)||t.match(/^\/([\s\S]*)\/(\w*)$/);return new RegExp(m[1],m[2]);};
const match=toRe(s.match), inputMatches=toRe(s.inputMatches);
let fired=0;
for (const [i,input] of calls.entries()) {
  const json=JSON.stringify(input);
  const field=typeof input.prompt==='string'?input.prompt:'';
  const m=field.match(match);
  const hit=m && inputMatches.test(json);
  if (hit) { fired++; console.log('FIRES  #'+i, JSON.stringify(m[0])); }
  else console.log('silent #'+i, (input.description||'').slice(0,40), '| isolation='+input.isolation);
}
console.log('fired', fired, 'of', calls.length);
"

